use vstd::prelude::*;
use vstd::string::*;

verus! {

spec fn is_lowercase_char(c: char) -> bool {
    c >= 'a' && c <= 'z'
}

spec fn all_lowercase_chars(v: Seq<char>) -> bool {
    forall|i: int| 0 <= i < v.len() ==> is_lowercase_char(v[i])
}

fn check_all_lowercase(v: &Vec<char>) -> (result: bool)
    ensures
        result == (v.len() > 0 && all_lowercase_chars(v@)),
{
    // First check if vector is empty
    if v.len() == 0 {
        return false;
    }
    
    let mut i: usize = 0;
    while i < v.len()
        invariant
            0 <= i <= v.len(),
            forall|j: int| 0 <= j < i ==> is_lowercase_char(v@[j]),
        decreases v.len() - i,
    {
        let c = v[i];
        if !('a' <= c && c <= 'z') {
            return false;
        }
        i = i + 1;
    }
    
    true
}

fn solve(input: Vec<char>) -> (result: Vec<char>)
    ensures
        result@.len() == 1,
        (check_all_lowercase(&input) ==> result@[0] == 'a'),
        (!check_all_lowercase(&input) ==> result@[0] == 'A'),
{
    let check_result = check_all_lowercase(&input);
    
    if check_result {
        let mut result_vec = Vec::new();
        result_vec.push('a');
        result_vec
    } else {
        let mut result_vec = Vec::new();
        result_vec.push('A');
        result_vec
    }
}

}
